import {today,totals,loanTotals,loanSchedule} from './domain.mjs';
import {translations} from './i18n.mjs';
import './account-i18n.mjs';
import './security-i18n.mjs';
import './workflow-i18n.mjs';
import './membership-i18n.mjs';
import './expense-i18n.mjs';
import './status-i18n.mjs';
import './settlement-i18n.mjs';
const blank=()=>({settings:{name:'e-Kimina',contribution:10000,frequency:'monthly',rate:2,term:6,goal:5000000},members:[],payments:[],loans:[],ledger:[],audit:[]});
let verificationFlow={},recoveryFlow={};
let state=blank(),lang='rw',actor='',filter='all',query='',user=null,groups=[],csrf='',loaded=false,currentGroup='',busy=false;
try{lang=localStorage.getItem('ekimina-language')||'rw';if(!translations[lang])lang='rw';}catch{}
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const t=k=>translations[lang][k]||k;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat(lang==='fr'?'fr-RW':'en-RW').format(n);
const amount=n=>`${fmt(n)} <small>RWF</small>`;
const member=id=>state.members.find(m=>m.id===id)||{name:'—',role:'member'};
const me=()=>member(actor);
const initial=n=>n.split(' ').map(w=>w[0]).slice(0,2).join('');
const treasurer=()=>me().role==='treasurer',leader=()=>me().role!=='member';
const paths={leaf:'M12 21v-9M12 16C3 16 3 9 3 5c7 0 9 4 9 7 0-7 4-10 10-10 0 8-3 12-10 12',overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',contributions:'M3 8h18v12H3zM3 8l3-5h12l3 5M3 12h18M16 16h2',loans:'M3 7h17M16 3l4 4-4 4M21 17H4M8 13l-4 4 4 4',members:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',reports:'M4 21V3h12l4 4v14zM8 16v-3M12 16V9M16 16v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',plus:'M12 5v14M5 12h14',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',chevron:'M9 5l7 7-7 7',arrow:'M4 12h16M15 7l5 5-5 5',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 12l3 3 5-6',menu:'M3 6h18M3 12h18M3 18h18',close:'M6 6l12 12M18 6L6 18',check:'M5 12l4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',home:'M3 10l9-7 9 7v11H3zM9 21v-8h6v8'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.leaf}"/></svg>`;
const btn=(label,action,ico='',secondary=false,extra='')=>`<button type="button" class="btn ${secondary?'secondary':''}" data-action="${action}" ${extra}>${ico?icon(ico):''}${esc(t(label))}</button>`;
const language=()=>`<select aria-label="${esc(t('language'))}" data-language><option value="rw" ${lang==='rw'?'selected':''}>Kinyarwanda</option><option value="en" ${lang==='en'?'selected':''}>English</option><option value="fr" ${lang==='fr'?'selected':''}>Français</option></select>`;
const badge=s=>`<span class="badge ${s}">${esc(t(s))}</span>`;
const person=id=>`<div class="person"><span class="avatar">${esc(initial(member(id).name))}</span><div><strong>${esc(member(id).name)}</strong><small>${esc(t(member(id).role))}</small></div></div>`;
const visiblePayments=()=>state.payments.filter(p=>leader()||p.member===actor);
const visibleLoans=()=>state.loans.filter(l=>leader()||l.member===actor);
async function api(url,method='GET',data,key){let response;try{response=await fetch(url,{method,credentials:'same-origin',headers:{...(data?{'Content-Type':'application/json'}:{}),...(csrf?{'X-CSRF-Token':csrf}:{}),...(key?{'Idempotency-Key':key}:{})},...(data?{body:JSON.stringify(data)}:{})});}catch{throw Error('connectionError');}let result;try{result=await response.json();}catch{throw Error('connectionError');}if(!response.ok){if(response.status===401&&result.error==='unauthorized'){user=null;csrf='';state=blank();groups=[];render();}throw Error(result.error||'serverError');}return result;}
async function refresh(preferred=currentGroup){const session=await api('/api/session');user=session.user;csrf=session.csrf;groups=session.groups;actor=user.id;currentGroup=groups.some(g=>g.id===preferred)?preferred:(groups[0]?.id||'');verificationFlow=session.phoneChallenge||{};state=currentGroup?await api('/api/groups/'+currentGroup):blank();loaded=true;render();}
function errorMessage(error){return translations[lang][error.message]||t('serverError');}
async function mutate(command,data,message,form){if(busy)return;busy=true;const key=form?(form.dataset.key||=crypto.randomUUID()):crypto.randomUUID();const submit=form?.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{const result=await api('/api/groups/'+currentGroup+'/commands','POST',{command,data},key);state=result.state;groups=groups.map(g=>g.id===currentGroup?{...g,name:state.settings.name}:g);modal.close();render();toast(t(message));}catch(e){const err=form?.querySelector('.error')||modal.querySelector('.error');if(err)err.textContent=errorMessage(e);else toast(errorMessage(e));}finally{busy=false;if(submit)submit.disabled=false;}}
let toastTimer;function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4500);}
function dialog(title,body,formId=''){modal.innerHTML=`<div class="dialog-head"><h2>${esc(t(title))}</h2><button class="icon-btn" data-action="close" aria-label="${esc(t('close'))}">${icon('close')}</button></div>${formId?`<form id="${formId}">`:''}${body}<div class="error" role="alert"></div>${formId?'</form>':''}`;modal.showModal();}
const formActions=(label='save')=>`<div class="form-actions">${btn('cancel','close','',true)}<button class="btn" type="submit">${esc(t(label))}</button></div>`;
const field=(key,name,type='text',value='',attrs='')=>`<label>${esc(t(key))}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const selectField=(key,name,options)=>`<label>${esc(t(key))}<select class="field" name="${name}">${options}</select></label>`;
const option=(v,label,selected=false)=>`<option value="${esc(v)}" ${selected?'selected':''}>${esc(label)}</option>`;
const brand=()=>`<a class="brand" href="#home"><span class="mark">${icon('leaf')}</span>e-Kimina<span style="color:#96b87c">.</span></a>`;
function render(){document.documentElement.lang=lang;document.title=`e-Kimina · ${t('tagline')}`;const route=location.hash.slice(1)||'overview';if(route==='recover'){recoveryPage();return;}if(route==='home'){landing();return;}const page=['overview','contributions','dues','loans','members','reports','settings'].includes(route)?route:'overview';if(!loaded){app.innerHTML='<div class="empty">'+esc(t('loading'))+'</div>';return;}if(!user){authPage(route==='register');return;}if(!currentGroup){onboarding();return;}const count=state.groupTotals.pending;app.innerHTML=`<div class="layout"><div class="mobile-shade" data-action="menu"></div><aside class="sidebar">${brand()}<div class="tagline">${esc(t('tagline'))}</div><div class="group-switch"><span class="group-logo">${icon('members')}</span><label style="min-width:0;flex:1">${esc(t('yourGroups'))}<select data-group aria-label="${esc(t('yourGroups'))}">${groups.map(g=>option(g.id,g.name,g.id===currentGroup)).join('')}</select></label></div><button class="btn ghost" data-action="groupOptions" style="margin-bottom:20px">${esc(t('createOrJoin'))}</button><div class="nav-label">${esc(t('workspace'))}</div><nav class="nav">${['overview','contributions','dues','loans','members','reports','settings'].map(k=>`<button data-route="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}>${icon(k)}${esc(t(k))}${k==='contributions'&&count&&treasurer()?`<span class="count">${count}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-box"><strong>${esc(t('help'))}</strong>${esc(t('helpText'))}<br><button data-action="help">${esc(t('guide'))} ↗</button></div><div class="profile"><span class="avatar">${esc(initial(me().name))}</span><div><strong>${esc(me().name)}</strong><small>${esc(t(me().role))}</small></div></div></div></aside><main class="workspace"><header class="topbar"><button class="icon-btn menu-toggle" data-action="menu" aria-label="Menu">${icon('menu')}</button><div class="breadcrumb">${esc(state.settings.name)} ${icon('chevron')} <span>${esc(t(page))}</span></div><div class="toolbar">${language()}<button class="icon-btn" data-action="notifications" aria-label="${esc(t('notifications'))}">${icon('bell')}${state.notifications?.some(n=>!n.read)?'<i class="dot"></i>':''}</button><button class="icon-btn" data-action="account" aria-label="${esc(t('account'))}"><span class="avatar">${esc(initial(me().name))}</span></button></div></header><div class="content"><div class="demo-bar"><span>${esc(t('developmentNotice'))}</span><button class="btn ghost" data-action="refresh">${esc(t('refresh'))}</button></div>${({overview,contributions,dues:duesPage,loans:loansPage,members:membersPage,reports,settings}[page])()}<footer class="footer"><span>${icon('shield')}${esc(t('privacy'))}</span><span>© ${new Date().getFullYear()} e-Kimina · <a href="#home">${esc(t('backHome'))}</a> · ${esc(t('serverSaved'))}</span></footer></div></main></div>`;}
const heading=(title,sub,actions='',eyebrow='')=>`<div class="heading"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(title)}</h1><p class="sub">${esc(t(sub))}</p></div><div class="actions">${actions}</div></div>`;
const stat=(title,value,ico,note,tag='')=>`<div class="stat"><div class="stat-top">${esc(t(title))}<span class="stat-icon">${icon(ico)}</span></div><strong>${value}</strong><div class="stat-foot">${tag?`<b>${esc(tag)}</b>`:''}${esc(t(note))}</div></div>`;
function overview(){const v=state.groupTotals,progress=Math.min(100,Math.round(v.savings/state.settings.goal*100));const personal=memberSavings(actor);return heading(me().role==='member'?t('memberDashboard'):`${t('welcome')} ${me().name.split(' ')[0]}.`,me().role==='member'?'memberDashboardSub':'welcomeSub',btn('export','export','download',true)+btn('record','payment','plus'),state.settings.name+' / '+t('overview'))+`${duesSummary()}<section class="hero"><div><div class="eyebrow">${esc(t('tagline'))}</div><h2>${esc(t('heroTitle'))}</h2><p>${esc(t('heroSub'))}</p></div><div class="hero-side"><div class="eyebrow">${esc(t('available'))}</div><strong>${fmt(v.cash)} <span style="font-size:12px">RWF</span></strong><small>${esc(t('confirmedOnly'))}</small></div></section><section class="stats">${stat(me().role==='member'?'remainingSavings':'savings',amount(me().role==='member'?personal:v.savings),'contributions','confirmedOnly')}${stat('outstanding',amount(me().role==='member'?visibleLoans().filter(l=>l.status==='active').reduce((a,l)=>a+loanTotals(l).outstanding,0):v.loans),'loans','includesInterest')}${stat('activeMembers',fmt(state.members.filter(m=>(m.status||'active')==='active').length),'members','membersOfGroup')}${stat('pendingPayments',visiblePayments().filter(p=>p.status==='pending').length,'clock','needsReview')}</section><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>${esc(t('savingsActivity'))}</h2><p class="sub">${esc(t('activitySub'))}</p></div><span class="badge active">RWF</span></div>${chart()}</section><section class="panel"><div class="panel-head"><div><h2>${esc(t('goal'))}</h2><p class="sub">${esc(t('goalSub'))}</p></div>${icon('leaf')}</div><div class="goal"><div class="goal-top"><div class="ring" style="--progress:${progress}%"><div>${progress}%<small>${esc(t('complete'))}</small></div></div><div><strong>${fmt(state.settings.goal)} RWF</strong><p>${esc(state.settings.name)}</p></div></div><div class="goal-row"><span>${esc(t('saved'))}</span><strong>${fmt(v.savings)} RWF</strong></div><div class="goal-row"><span>${esc(t('remaining'))}</span><strong>${fmt(Math.max(0,state.settings.goal-v.savings))} RWF</strong></div><div class="goal-note">${esc(t('goalNote'))}</div></div></section></div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>${esc(t('recent'))}</h2><p class="sub">${esc(t('recentSub'))}</p></div><button class="btn ghost" data-route="contributions">${esc(t('viewAll'))} ${icon('arrow')}</button></div>${paymentTable(visiblePayments().slice(0,5),false)}<div class="panel-foot"><span>${visiblePayments().length} ${esc(t('contributions').toLowerCase())}</span><span>${esc(t('external'))}</span></div></section><section class="panel"><div class="panel-head"><h2>${esc(t('nextSteps'))}</h2></div>${[['reviewTitle','reviewText','review','contributions','contributions'],['loanTitle','loanText','openLoans','loans','loans'],['rulesTitle','rulesText','openSettings','settings','settings']].map(([a,b,c,r,i])=>`<div class="task"><span class="task-icon">${icon(i)}</span><div><strong>${esc(t(a))}</strong><p>${esc(t(b))}</p><button class="btn ghost" data-route="${r}">${esc(t(c))} →</button></div></div>`).join('')}</section></div>`;}
function chart(){const months=Array.from({length:6},(_,i)=>{const d=new Date(today()+'T12:00:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-5+i);return {period:d.toISOString().slice(0,7),label:new Intl.DateTimeFormat(lang==='rw'?'rw-RW':lang,{month:'short',timeZone:'Africa/Kigali'}).format(d)};});const targets=months.map(m=>state.activityTargets?.[m.period]||0);const values=months.map(m=>state.activity?.[m.period]||0);if(values.some(n=>n<0))return '<div class="chart"><p class="sub">'+esc(t('netActivity'))+'</p><table><tbody>'+months.map((m,i)=>'<tr><td>'+esc(m.label)+'</td><td>'+fmt(values[i])+' RWF</td></tr>').join('')+'</tbody></table></div>';const max=Math.max(...targets,...values,1);return `<div class="chart"><div class="chart-legend"><span>${esc(t('collected'))}</span><span>${esc(t('target'))}</span></div><div class="chart-area" role="img" aria-label="${esc(months.map((m,i)=>`${m.label}: ${values[i]} RWF; ${t('target')}: ${targets[i]} RWF`).join('. '))}"><div class="yaxis"><span>${fmt(max)}</span><span>${fmt(Math.round(max*.75))}</span><span>${fmt(Math.round(max*.5))}</span><span>${fmt(Math.round(max*.25))}</span><span>0</span></div><div class="bars">${months.map((m,i)=>`<div class="bar-group"><div class="bar" style="height:${values[i]/max*85}%" title="${esc(m.label)}: ${values[i]} RWF"></div><div class="bar light" style="height:${targets[i]/max*85}%"></div><span class="bar-label">${esc(m.label)}</span></div>`).join('')}</div></div></div>`;}
function paymentTable(list,action=true){return list.length?`<div class="table-wrap"><table><thead><tr>${['name','amount','method','status',...(action?['actions']:[])].map(k=>`<th>${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${list.map(p=>`<tr><td>${person(p.member)}</td><td><span class="amount">${fmt(p.amount)} RWF</span><div class="statusline">${esc(t(p.purpose))} · ${esc(p.date)}</div></td><td>${esc(t(p.method))}<div class="statusline">${esc(p.reference||'—')}</div>${receiptLink(p)}</td><td>${badge(p.reversedAt?'reversed':p.status)}${p.reason?`<div class="statusline" style="white-space:normal;max-width:180px">${esc(p.reason)}</div>`:''}</td>${action?`<td>${treasurer()&&p.status==='pending'?btn('review','reviewPayment','',true,`data-id="${p.id}"`):`<button class="btn ghost" data-action="paymentDetail" data-id="${p.id}">${esc(t('detail'))}</button>`}</td>`:''}</tr>`).join('')}</tbody></table></div>`:`<div class="empty">${esc(t('noRecords'))}</div>`;}
function contributions(){const list=visiblePayments().filter(p=>(filter==='all'||(p.reversedAt?'reversed':p.status)===filter)&&`${member(p.member).name} ${p.reference}`.toLowerCase().includes(query.toLowerCase()));return heading(t('contributions'),'paymentSub',btn('record','payment','plus'))+`<section class="panel"><div class="panel-head"><h2>${esc(t('recent'))}</h2><span class="badge pending">${visiblePayments().filter(p=>p.status==='pending').length} ${esc(t('reviewCount'))}</span></div><div class="tabs">${['all','pending','approved','rejected','reversed'].map(k=>`<button data-filter="${k}" class="${filter===k?'active':''}">${esc(t(k))}</button>`).join('')}</div><div class="filterbar"><input id="payment-search" value="${esc(query)}" placeholder="${esc(t('search'))}" aria-label="${esc(t('search'))}"></div><div id="payments-table">${paymentTable(list)}</div></section>`;}
function loansPage(){return heading(t('loans'),'loanSub',btn('requestLoan','loan','plus'))+`<div class="callout">${esc(t('loanInfo'))}</div><section class="panel"><div class="panel-head"><h2>${esc(t('loans'))}</h2><span class="muted" style="font-size:11px">${visibleLoans().length}</span></div><div class="table-wrap"><table><thead><tr>${['name','principal','interest','term','balance','status','actions'].map(k=>`<th>${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${visibleLoans().map(l=>{const v=loanTotals(l);return `<tr><td>${person(l.member)}<div class="statusline">${esc(l.purpose)}</div></td><td class="amount">${fmt(l.amount)} RWF</td><td>${fmt(v.interest)} RWF<div class="statusline">${l.rate}% / ${esc(t('monthly'))} · ${esc(t(l.interestMethod||'flat'))}</div></td><td>${l.term} ${esc(t('months'))}</td><td>${['active','repaid'].includes(l.status)?fmt(v.outstanding)+' RWF':'—'}</td><td>${badge(l.status)}${l.status==='approved'?`<div class="statusline">${esc(t('approvedLoan'))}</div>`:''}</td><td>${l.status==='submitted'&&me().role==='chairperson'?btn('loanTitle','reviewLoan','',true,`data-id="${l.id}"`):l.status==='approved'&&treasurer()?btn('disburse','disburse','',false,`data-id="${l.id}"`):`<button class="btn ghost" data-action="loanDetail" data-id="${l.id}">${esc(t('detail'))}</button>`}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function membersPage(){return heading(t('members'),'membersSub',me().role==='chairperson'?btn('inviteMember','addMember','plus'):'')+`<section class="panel"><div class="panel-head"><h2>${esc(state.settings.name)}</h2><span class="badge">${state.members.length} ${esc(t('members'))}</span></div><div class="table-wrap"><table><thead><tr>${['name',...(leader()?['phone']:[]),'role','status'].map(k=>`<th>${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${state.members.map(m=>`<tr><td>${person(m.id)}</td>${leader()?`<td>${esc(m.phone)}</td>`:''}<td>${esc(t(m.role))}</td><td>${badge(m.status||'active')}${me().role==='chairperson'&&m.id!==actor?btn('manageMember','manageMember','',true,'data-id="'+esc(m.id)+'"'):''}</td></tr>`).join('')}</tbody></table></div></section>${membershipInvites()}${announcementsPanel()}`;}
function reports(){const entries=state.ledger.filter(e=>leader()||e.member===actor);return heading(t('reports'),'reportSub',btn('export','export','download'))+`<div class="report-tiles"><section class="panel report-tile">${icon('reports')}<h2>${esc(t('statement'))}</h2><p>${esc(t('statementText'))}</p>${btn('download','export','download',true)}</section><section class="panel report-tile">${icon('shield')}<h2>${esc(t('audit'))}</h2><p>${esc(t('auditText'))}</p><strong>${state.audit.filter(e=>leader()||e.actor===actor).length}</strong></section><section class="panel report-tile">${icon('contributions')}<h2>${esc(t('available'))}</h2><p>${esc(t('confirmedOnly'))}</p><strong>${fmt(state.groupTotals.cash)} RWF</strong></section></div><section class="panel"><div class="panel-head"><h2>${esc(t('statement'))}</h2></div><div class="table-wrap"><table><thead><tr>${['date','name','event','amount','actions'].map(k=>`<th>${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${entries.map(e=>`<tr><td>${esc(e.date)}</td><td>${e.member?esc(member(e.member).name):esc(state.settings.name)}</td><td>${esc(e.kind==='opening'?t('goalNote'):t(e.kind==='disbursement'?'disbursedEvent':e.kind==='reversal'?'reversed':e.kind))}</td><td class="amount">${e.kind==='reversal'?'−':''}${fmt(e.amount)} RWF</td><td>${reversalAction(e)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>${esc(t('auditTitle'))}</h2></div>${auditTable()}</section>${reconciliationPanel()}${expensePanel()}${settlementPanel()}`;}
const eventLabel=k=>({submitted:'submittedEvent',approved:'approvedEvent',rejected:'rejectedEvent',loanRequested:'loanRequested',disbursed:'disbursedEvent',settings:'settingsChanged',groupCreated:'groupCreatedEvent',invitationCreated:'invitationCreatedEvent',memberJoined:'memberJoinedEvent',reversed:'reversedEvent',reconciled:'reconciledEvent',announcement:'announcementEvent',memberStatus:'memberStatusChanged',memberCreated:'memberCreated'}[k]||k);
function auditTable(){const list=state.audit.filter(e=>leader()||e.actor===actor);return list.length?`<div class="table-wrap"><table><thead><tr>${['date','actor','event','detail'].map(k=>`<th>${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${list.slice(0,50).map(e=>`<tr><td>${esc(new Intl.DateTimeFormat(lang==='rw'?'rw-RW':lang,{dateStyle:'short',timeStyle:'short',timeZone:'Africa/Kigali'}).format(new Date(e.date)))}</td><td>${esc(member(e.actor).name)}</td><td>${esc(t(eventLabel(e.action)))}</td><td class="audit-detail">${esc(e.detail)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${esc(t('noRecords'))}</div>`;}
function settings(){const s=state.settings;return heading(t('settings'),'settingsSub')+`<div class="settings-grid"><section class="panel form-panel"><h2>${esc(t('settings'))}</h2><p class="sub" style="margin:10px 0 23px">${esc(t('settingsInfo'))}</p><form id="settings-form"><fieldset ${me().role!=='chairperson'?'disabled':''} style="border:0;padding:0;margin:0"><div class="form-grid">${field('groupName','name','text',s.name,'required maxlength="80"')}${field('contributionAmount','contribution','number',s.contribution,'required min="1" max="1000000000" step="1"')}${selectField('frequency','frequency',option('monthly',t('monthly'),s.frequency==='monthly'))}${field('rate','rate','number',s.rate,'required min="0" max="100" step="0.01"')}${field('maxTerm','term','number',s.term,'required min="1" max="60" step="1"')}${field('goalAmount','goal','number',s.goal,'required min="1" max="1000000000" step="1"')}${interestSelect(s.interestMethod)}${trackingControls(s)}</div>${me().role==='chairperson'?formActions():`<div class="callout">${esc(t('readOnly'))} · ${esc(t('chairperson'))}</div>`}</fieldset><div class="error" role="alert"></div></form></section><section class="panel form-panel" style="align-self:start"><h2>${esc(t('account'))}</h2><p class="sub" style="margin:15px 0">${esc(t('serverSavedInfo'))}</p>${btn('account','account','shield',true)}<div class="callout">${esc(t('developmentNotice'))}</div></section></div>`;}
function landing(){app.innerHTML=`<div class="landing"><header class="landing-nav">${brand()}<div class="actions">${language()}${btn('tryDemo','openDemo','arrow')}</div></header><section class="landing-hero"><div><div class="eyebrow">${esc(t('builtFor'))}</div><h1>${esc(t('landingTitle')).split('\n').map((x,i)=>i?`<em>${x}</em>`:x).join('<br>')}</h1><p>${esc(t('landingText'))}</p><div class="actions" style="margin-top:28px">${btn('tryDemo','openDemo','arrow')}${btn('how','help','',true)}</div><p style="font-size:11px;margin-top:20px">${icon('shield')}${esc(t('external'))}</p></div><div class="landing-card"><div class="split">${icon('leaf')}<span>e-Kimina</span></div><div class="eyebrow" style="margin-top:35px">${esc(t('tagline'))}</div><h2>${esc(t('yourGroupOnline'))}</h2><p style="color:#cadac6;font-size:13px">Kinyarwanda · English · Français</p><div class="landing-mini"><strong>${esc(t('paymentSub'))}</strong><p>${esc(t('external'))}</p></div><div class="statusline" style="color:#d2dfca;margin-top:20px">${esc(t('developmentNotice'))}</div></div></section><section class="landing-features"><div><div class="eyebrow">e-Kimina</div><h1 style="font-size:28px">${esc(t('simple'))}</h1><div class="feature-grid">${['contributions','loans','members'].map((i,n)=>`<article class="feature">${icon(i)}<h2>${esc(t('feature'+(n+1)))}</h2><p>${esc(t('feature'+(n+1)+'Text'))}</p></article>`).join('')}</div></div></section><footer class="landing-bottom"><div class="split">${brand()}<span class="sub">Kinyarwanda · English · Français</span></div><p class="sub" style="margin-top:25px">${esc(t('demoWarning'))}</p></footer></div>`;}
function paymentDialog(){const active=state.loans.filter(l=>l.member===actor&&l.status==='active');dialog('record',`<p class="dialog-sub">${esc(t('paymentSub'))}</p><div class="form-grid">${field('amount','amount','number',state.settings.contribution,'required min="1" max="1000000000" step="1"')}${field('date','date','date',today(),`required max="${today()}"`)}${selectField('method','method',['momo','cash','bank'].map(k=>option(k,t(k))).join(''))}${selectField('purpose','purpose',option('contribution',t('contribution'))+(active.length?option('repayment',t('repayment')):''))}<div id="period-field">${field('period','period','month',today().slice(0,7),'required')}</div><div id="loan-field" hidden>${selectField('loan','loan',active.map(l=>option(l.id,`${fmt(loanTotals(l).outstanding)} RWF · ${l.purpose}`)).join(''))}</div><label class="full">${esc(t('reference'))} (${esc(t('optional'))})<input name="reference" maxlength="100"></label></div><div class="callout">${esc(t('paymentInfo'))}</div><label style="margin-top:16px">${esc(t('receiptFile'))}<input name="receiptFile" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"><small>${esc(t('receiptHelp'))}</small></label>${formActions('send')}`,'payment-form');}
function loanDialog(){dialog('requestLoan',`<div class="form-grid">${field('amount','amount','number','100000','required min="1" max="1000000000" step="1"')}${field('term','term','number',state.settings.term,`required min="1" max="${state.settings.term}" step="1"`)}<label class="full">${esc(t('loanPurpose'))}<textarea name="purpose" required maxlength="300"></textarea></label></div><div class="callout">${esc(t('loanInfo'))}<br><strong>${state.settings.rate}% · ${esc(t('monthly'))} · ${esc(t(state.settings.interestMethod))}</strong></div>${formActions('requestLoan')}`,'loan-form');}
function reviewDialog(id,isLoan=false){const p=(isLoan?state.loans:state.payments).find(p=>p.id===id);if(!p)return;dialog(isLoan?'loanTitle':'reviewTitle',`<div class="dialog-sub">${person(p.member)}</div><h2>${fmt(p.amount)} RWF</h2><p class="sub">${esc(p.date||'')} · ${esc(p.reference||p.purpose)}</p>${receiptLink(p)}<div class="callout">${esc(t(isLoan?'loanInfo':'reviewInfo'))}</div>${selectField('status','decision',['approved','rejected'].map(k=>option(k,t(k))).join(''))}<label style="margin-top:15px">${esc(t('reason'))}<textarea name="reason" maxlength="300"></textarea></label><input type="hidden" name="id" value="${p.id}">${formActions('confirm')}`,isLoan?'review-loan-form':'review-payment-form');}
app.addEventListener('input',e=>{if(e.target.id==='payment-search'){query=e.target.value;document.querySelector('#payments-table').innerHTML=paymentTable(visiblePayments().filter(p=>(filter==='all'||(p.reversedAt?'reversed':p.status)===filter)&&`${member(p.member).name} ${p.reference}`.toLowerCase().includes(query.toLowerCase())));}});
document.addEventListener('change',e=>{if(e.target.matches('[data-language]')){lang=e.target.value;try{localStorage.setItem('ekimina-language',lang);}catch{}render();}if(e.target.matches('[data-group]')){filter='all';query='';refresh(e.target.value).catch(e=>toast(errorMessage(e)));}if(e.target.name==='purpose'&&e.target.closest('#payment-form')){const repay=e.target.value==='repayment';document.querySelector('#period-field').hidden=repay;document.querySelector('#period-field input').required=!repay;document.querySelector('#loan-field').hidden=!repay;}});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-route],[data-filter],[data-dues]');if(!target)return;if(target.dataset.dues){duesFilter=target.dataset.dues;render();return;}if(target.dataset.route){filter='all';query='';location.hash=target.dataset.route;return;}if(target.dataset.filter){filter=target.dataset.filter;render();return;}const id=target.dataset.id;switch(target.dataset.action){case 'openDemo':location.hash=user?'overview':'login';break;case 'register':location.hash='register';break;case 'login':location.hash='login';break;case 'refresh':refresh().catch(e=>toast(errorMessage(e)));break;case 'account':accountDialog();break;case 'logout':logout();break;case 'revokeSession':revokeSession(id);break;case 'groupOptions':groupOptions();break;case 'createGroup':createGroupDialog();break;case 'joinGroup':joinDialog();break;case 'menu':document.querySelector('.sidebar')?.classList.toggle('open');document.querySelector('.mobile-shade')?.classList.toggle('open');break;case 'close':discardDraftReceipt();modal.close();break;case 'help':dialog('howTitle',`<p style="font-size:13px;white-space:pre-line">${esc(t('howText'))}</p>${btn('close','close')}`);break;case 'notifications':inboxDialog();break;case 'publishAnnouncement':announcementDialog();break;case 'markRead':markNotices();break;case 'reverseEntry':reverseDialog(id);break;case 'reconcile':reconcileDialog();break;case 'payment':paymentDialog();break;case 'loan':loanDialog();break;case 'reviewPayment':reviewDialog(id);break;case 'reviewLoan':reviewDialog(id,true);break;case 'disburse':{const l=state.loans.find(l=>l.id===id);dialog('disburse',`<p class="dialog-sub">${esc(member(l.member).name)} · ${fmt(l.amount)} RWF</p><div class="callout">${esc(t('disburseInfo'))}</div>${field('reference','reference','text','','required maxlength="100"')}<input type="hidden" name="id" value="${id}">${formActions('disburse')}`,'disburse-form');break;}case 'newExpense':expenseDialog();break;case 'reviewExpense':expenseReviewDialog(id);break;case 'payExpense':expensePayDialog(id);break;case 'withdrawalCancel':withdrawalCancelDialog(id);break;case 'withdrawalRequest':withdrawalDialog();break;case 'withdrawalReview':withdrawalReviewDialog(id);break;case 'withdrawalPay':withdrawalPayDialog(id);break;case 'memberStatus':memberStatusDialog(id);break;case 'manageMember':manageMemberDialog(id);break;case 'revokeInvite':revokeInviteDialog(id);break;case 'addMember':inviteDialog();break;case 'export':download();break;case 'paymentDetail':{const p=state.payments.find(p=>p.id===id);dialog('confirmation',`${person(p.member)}<h2 style="margin-top:20px">${fmt(p.amount)} RWF</h2><p>${badge(p.reversedAt?'reversed':p.status)}</p><p class="sub">${esc(p.date)} · ${esc(t(p.method))} · ${esc(p.reference||'—')}</p>${receiptLink(p)}${p.reviewedBy?`<div class="callout">${esc(t('approvedBy'))}: ${esc(member(p.reviewedBy).name)}<br>${esc(p.reviewedAt)}${p.reason?'<br>'+esc(p.reason):''}</div>`:''}${btn('close','close')}`);break;}case 'loanDetail':{const l=state.loans.find(l=>l.id===id),v=loanTotals(l);dialog('loans',`${person(l.member)}<p>${badge(l.status)}</p><p class="sub">${esc(l.purpose)}</p><div class="goal-row"><span>${esc(t('principal'))}</span><strong>${fmt(l.amount)} RWF</strong></div><div class="goal-row"><span>${esc(t('interest'))} · ${l.rate}% / ${esc(t('monthly'))}</span><strong>${fmt(v.interest)} RWF</strong></div><div class="goal-row"><span>${esc(t('totalDue'))}</span><strong>${fmt(v.total)} RWF</strong></div><div class="goal-row"><span>${esc(t('term'))}</span><strong>${l.term}</strong></div><div class="callout">${esc(t(l.interestMethod||'flat'))} · ${esc(t('allocation'))}</div>${scheduleTable(l)}${l.reason?`<p>${esc(t('reason'))}: ${esc(l.reason)}</p>`:''}${btn('close','close')}`);break;}}});
document.addEventListener('submit',e=>{const f=e.target,id=f.getAttribute('id');if(!id)return;e.preventDefault();const data=Object.fromEntries(new FormData(f));if(id==='payment-form'){submitPaymentWithReceipt(f,data);return;}const commands={
'expense-form':['expense.request',{...data,amount:Number(data.amount)},'expenseSaved'],
'expense-review-form':['expense.review',data,'expenseSaved'],
'expense-pay-form':['expense.pay',data,'expenseSaved'],
'withdrawal-cancel-form':['withdrawal.cancel',data,'savedSettings'],
'withdrawal-form':['withdrawal.request',{amount:Number(data.amount),reason:data.reason},'savedSettings'],
'withdrawal-review-form':['withdrawal.review',data,'savedSettings'],
'withdrawal-pay-form':['withdrawal.pay',data,'savedSettings'],
'member-status-form':['member.status',data,'membershipSaved'],
'member-role-form':[data.operation==='transfer'?'chair.transfer':'member.role',{id:data.id,role:data.role,reason:data.reason,confirm:data.confirm==='on'},'membershipSaved'],
'revoke-invite-form':['invitation.revoke',{id:data.id},'membershipSaved'],
'payment-form':['payment.submit',{...data,amount:Number(data.amount)},'paymentSent'],
'loan-form':['loan.request',{...data,amount:Number(data.amount),term:Number(data.term)},'loanSent'],
'review-payment-form':['payment.review',data,'reviewed'],
'review-loan-form':['loan.review',data,'loanApproved'],
'disburse-form':['loan.disburse',data,'disbursed'],
'announcement-form':['announcement.publish',data,'announcementSaved'],
'reverse-form':['ledger.reverse',data,'reversalSaved'],
'reconcile-form':['reconciliation.record',{cash:Number(data.cash),momo:Number(data.momo),bank:Number(data.bank),note:data.note},'reconciliationSaved'],
'settings-form':['settings.update',{...data,contribution:Number(data.contribution),rate:Number(data.rate),term:Number(data.term),goal:Number(data.goal),trackContributions:data.trackContributions==='on',dueDay:Number(data.dueDay),trackingStart:data.trackingStart},'savedSettings']};
if(commands[id]){mutate(...commands[id],f);return;}if(['request-code-form','verify-code-form','recovery-request-form','recovery-reset-form'].includes(id)){submitSecurityForm(f,id,data);return;}accountSubmit(f,id,data);});
function download(){const rows=[[t('date'),t('name'),t('event'),t('amount'),'RWF',t('reference'),'record_id','original_kind','reverses','cash_change'],...state.ledger.filter(e=>leader()||e.member===actor).map(e=>[e.date,e.member?member(e.member).name:state.settings.name,e.kind==='opening'?t('goalNote'):t(e.kind==='disbursement'?'disbursedEvent':e.kind==='reversal'?'reversed':e.kind),e.amount,'RWF',e.detail||'',e.id,e.originalKind||e.kind,e.reverses||'',(e.kind==='reversal'?-1:1)*e.amount*(['contribution','repayment','opening'].includes(e.originalKind||e.kind)?1:-1)])];const safe=v=>{let val=String(v);if(/^[=+@\-\t\r]/.test(val))val="'"+val;return '"'+val.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`e-kimina-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('exported'));}
window.addEventListener('hashchange',render);
document.addEventListener('input',e=>{if(e.target.form)delete e.target.form.dataset.key;});
document.addEventListener('change',e=>{if(e.target.form)delete e.target.form.dataset.key;});
refresh().catch(e=>{loaded=true;user=null;render();if(e.message!=='unauthorized')toast(errorMessage(e));});
window.addEventListener('focus',()=>{if(user&&!modal.open&&!busy)refresh().catch(e=>toast(errorMessage(e)));});

function authPage(register=false){
 app.innerHTML='<div class="landing"><header class="landing-nav">'+brand()+language()+'</header><div class="auth-layout"><div><div class="eyebrow">'+esc(t('builtFor'))+'</div><h1>'+esc(t('authIntro'))+'</h1><p class="sub">'+esc(t('landingText'))+'</p><div class="callout">'+esc(t('developmentNotice'))+'</div></div><section class="panel form-panel"><h2>'+esc(t(register?'register':'signIn'))+'</h2><form id="'+(register?'register-form':'login-form')+'"><div class="auth-fields">'+(register?field('name','name','text','','required maxlength="80" autocomplete="name"'):'')+field('phone','phone','tel','','required maxlength="25" autocomplete="username"')+field('password','password','password','','required maxlength="128" autocomplete="'+(register?'new-password':'current-password')+'"')+'<p class="sub">'+esc(t('passwordHint'))+'</p><div class="error" role="alert"></div><button type="submit" class="btn">'+esc(t(register?'register':'signIn'))+'</button></div></form><p><a href="#recover">'+esc(t('forgotPassword'))+'</a></p><p><a href="#'+(register?'login':'register')+'">'+esc(t(register?'signIn':'register'))+'</a> · <a href="#home">'+esc(t('home'))+'</a></p></section></div></div>';
}
function onboarding(){app.innerHTML='<div class="landing"><header class="landing-nav">'+brand()+language()+btn('logout','logout','',true)+'</header><section class="onboarding panel form-panel"><div class="eyebrow">'+esc(user.name)+'</div><h1>'+esc(t('createOrJoin'))+'</h1><p class="sub">'+esc(t('groupIntro'))+'</p><div class="callout">'+esc(t('developmentNotice'))+'</div><div class="actions">'+btn('createGroup','createGroup','plus')+btn('joinGroup','joinGroup','members',true)+'</div></section></div>';}
function groupOptions(){dialog('createOrJoin','<p class="dialog-sub">'+esc(t('groupIntro'))+'</p><div class="actions">'+btn('createGroup','createGroup','plus')+btn('joinGroup','joinGroup','members',true)+'</div>');}
function interestSelect(value){return selectField('interestMethod','interestMethod',['flat','reducing'].map(k=>option(k,t(k),k===value)).join(''));}
function createGroupDialog(){modal.close();dialog('createGroup','<p class="dialog-sub">'+esc(t('createIntro'))+'</p><div class="form-grid">'+field('groupName','name','text','','required maxlength="80"')+field('contributionAmount','contribution','number',10000,'required min="1" max="1000000000" step="1"')+field('rate','rate','number',2,'required min="0" max="100" step="0.01"')+field('maxTerm','term','number',6,'required min="1" max="60" step="1"')+field('goalAmount','goal','number',5000000,'required min="1" max="1000000000" step="1"')+selectField('frequency','frequency',option('monthly',t('monthly')))+interestSelect('flat')+trackingControls({trackContributions:true,dueDay:31,trackingStart:today().slice(0,7)})+'</div><div class="callout">'+esc(t('settingsInfo'))+'</div>'+formActions('createGroup'),'create-group-form');}
function joinDialog(){modal.close();dialog('joinGroup','<p class="dialog-sub">'+esc(t('groupIntro'))+'</p>'+field('joinToken','token','text','','required maxlength="100" autocomplete="off"')+formActions('joinGroup'),'join-group-form');}
function inviteDialog(){dialog('inviteMember','<p class="dialog-sub">'+esc(t('inviteIntro'))+'</p><div class="form-grid">'+field('phone','phone','tel','','required maxlength="25"')+selectField('role','role',['member','treasurer','secretary'].map(r=>option(r,t(r))).join(''))+'</div>'+formActions('inviteMember'),'invite-form');}
async function accountSubmit(form,id,data){
 if(busy)return;busy=true;const button=form.querySelector('[type="submit"]');button.disabled=true;
 try{
  if(id==='login-form'||id==='register-form'){const result=await api('/api/auth/'+(id==='login-form'?'login':'register'),'POST',{...data,language:lang});user=result.user;csrf=result.csrf;await refresh();location.hash='overview';toast(t('signInSuccess'));}
  if(id==='create-group-form'||id==='join-group-form'){const creating=id==='create-group-form';const result=await api(creating?'/api/groups':'/api/groups/join','POST',creating?{...data,contribution:Number(data.contribution),rate:Number(data.rate),term:Number(data.term),goal:Number(data.goal),trackContributions:data.trackContributions==='on',dueDay:Number(data.dueDay),trackingStart:data.trackingStart}:data);await refresh(result.id);modal.close();location.hash='overview';toast(t(creating?'groupCreated':'joinedGroup'));}
  if(id==='invite-form'){const result=await api('/api/groups/'+currentGroup+'/invitations','POST',data);await refresh();modal.close();dialog('inviteCreated','<p class="dialog-sub">'+esc(t('inviteWarning'))+'</p><label>'+esc(t('invitationCode'))+'<input readonly value="'+esc(result.token)+'" autocomplete="off"></label><div class="callout">'+esc(data.phone)+' · '+esc(t(data.role))+'</div>'+btn('close','close'));}
 }catch(e){const err=form.querySelector('.error');if(err)err.textContent=errorMessage(e);else toast(errorMessage(e));}finally{busy=false;button.disabled=false;}
}
async function logout(){if(busy)return;try{await api('/api/auth/logout','POST',{});modal.close();user=null;csrf='';actor='';groups=[];currentGroup='';state=blank();location.hash='login';render();toast(t('logoutSuccess'));}catch(e){toast(errorMessage(e));}}
async function accountDialog(){try{const result=await api('/api/sessions');dialog('account','<p class="dialog-sub">'+esc(user.name)+' · '+esc(user.phone)+'</p><p class="sub">'+esc(t('verificationDisabled'))+'</p><h3>'+esc(t('activeSessions'))+'</h3>'+result.sessions.map(s=>'<div class="goal-row"><span>'+esc(new Intl.DateTimeFormat(lang==='rw'?'rw-RW':lang,{dateStyle:'short',timeStyle:'short',timeZone:'Africa/Kigali'}).format(new Date(s.created_at)))+(s.current?' · '+esc(t('currentSession')):'')+'</span>'+(s.current?'':btn('revoke','revokeSession','',true,'data-id="'+s.id+'"'))+'</div>').join('')+'<div class="form-actions">'+btn('logout','logout','',true)+btn('close','close')+'</div>');}catch(e){toast(errorMessage(e));}}
async function revokeSession(id){try{await api('/api/sessions/'+encodeURIComponent(id),'DELETE',{});modal.close();await accountDialog();toast(t('sessionRevoked'));}catch(e){toast(errorMessage(e));}}
function scheduleTable(l){return '<div class="table-wrap"><table><thead><tr>'+['date','principal','interest','amount','balance'].map(k=>'<th>'+esc(t(k))+'</th>').join('')+'</tr></thead><tbody>'+loanSchedule(l).map(e=>'<tr><td>'+(e.dueDate||'#'+e.number)+'</td><td>'+fmt(e.principal)+'</td><td>'+fmt(e.interest)+'</td><td>'+fmt(e.total)+'</td><td>'+fmt(e.outstanding)+'</td></tr>').join('')+'</tbody></table></div>';}

function securityInput(){return field('verificationCode','code','text','','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"');}
function codeMeta(flow){return '<p class="sub">'+esc(t('codeExpires'))+' '+esc(new Intl.DateTimeFormat(lang==='rw'?'rw-RW':lang,{timeStyle:'short',timeZone:'Africa/Kigali'}).format(new Date(flow.expiresAt)))+'</p>';}
let codeTimer;
function startCodeTimer(){clearInterval(codeTimer);const update=()=>{const buttons=document.querySelectorAll('[data-resend-at]');if(!buttons.length){clearInterval(codeTimer);return;}buttons.forEach(b=>{const seconds=Math.max(0,Math.ceil((Number(b.dataset.resendAt)-Date.now())/1000));b.disabled=seconds>0;b.textContent=t('resendCode')+(seconds?' ('+seconds+'s)':'');});};update();codeTimer=setInterval(update,1000);}
function requestCodeForm(flow){return '<form id="request-code-form"><div class="error" role="alert"></div><button type="submit" class="btn secondary" '+(flow.challengeId?'data-resend-at="'+(flow.expiresAt-9*60000)+'"':'')+'>'+esc(t(flow.challengeId?'resendCode':'requestCode'))+'</button></form>';}
function verificationPage(){app.innerHTML='<div class="landing"><header class="landing-nav">'+brand()+'<div class="actions">'+language()+btn('logout','logout','',true)+'</div></header><div class="auth-layout"><div><div class="eyebrow">e-Kimina</div><h1>'+esc(t('verifyPhone'))+'</h1><p class="sub">'+esc(user.phone)+'</p><div class="callout">'+esc(t('localCodeNotice'))+'</div><p class="sub">'+esc(t('verificationGate'))+'</p></div><section class="panel form-panel"><h2>'+esc(t('verifyPhone'))+'</h2><p class="sub" style="margin:16px 0">'+esc(t('terminalInstructions'))+'</p>'+(verificationFlow.challengeId?'<form id="verify-code-form"><div class="auth-fields">'+securityInput()+codeMeta(verificationFlow)+'<div class="error" role="alert"></div><button type="submit" class="btn">'+esc(t('confirmPhone'))+'</button></div></form><div style="margin-top:20px">'+requestCodeForm(verificationFlow)+'</div>':requestCodeForm(verificationFlow))+'</section></div></div>';startCodeTimer();}
function recoveryPage(){const flow=recoveryFlow;app.innerHTML='<div class="landing"><header class="landing-nav">'+brand()+language()+'</header><div class="auth-layout"><div><div class="eyebrow">e-Kimina</div><h1>'+esc(t('recoverAccount'))+'</h1><p class="sub">'+esc(t('recoveryIntro'))+'</p><div class="callout">'+esc(t('localCodeNotice'))+'</div><a class="sub" href="#login">'+esc(t('signIn'))+' →</a></div><section class="panel form-panel"><h2>'+esc(t(flow.challengeId?'setNewPassword':'recoverAccount'))+'</h2>'+(flow.challengeId?'<p class="sub" style="margin:15px 0">'+esc(t('recoveryGeneric'))+'</p><form id="recovery-reset-form"><div class="auth-fields">'+securityInput()+field('newPassword','password','password','','required minlength="12" maxlength="128" autocomplete="new-password"')+field('confirmPassword','confirmPassword','password','','required minlength="12" maxlength="128" autocomplete="new-password"')+codeMeta(flow)+'<div class="error" role="alert"></div><button type="submit" class="btn">'+esc(t('resetPassword'))+'</button></div></form><form id="recovery-request-form" style="margin-top:20px"><input type="hidden" name="phone" value="'+esc(flow.phone)+'"><div class="error" role="alert"></div><button type="submit" class="btn secondary" data-resend-at="'+(flow.expiresAt-9*60000)+'">'+esc(t('resendCode'))+'</button></form>':'<form id="recovery-request-form"><div class="auth-fields">'+field('phone','phone','tel','','required maxlength="25" autocomplete="username"')+'<div class="error" role="alert"></div><button type="submit" class="btn">'+esc(t('requestCode'))+'</button></div></form>')+'</section></div></div>';startCodeTimer();}
async function submitSecurityForm(form,id,data){
 if(busy)return;busy=true;const button=form.querySelector('[type="submit"]');button.disabled=true;
 try{
  if(id==='request-code-form'){const result=await api('/api/auth/phone/request','POST',{});if(result.alreadyVerified){await refresh();return;}verificationFlow=result;render();toast(t('codeRequested'));}
  if(id==='verify-code-form'){const result=await api('/api/auth/phone/confirm','POST',{challengeId:verificationFlow.challengeId,code:data.code});user=result.user;csrf=result.csrf;verificationFlow={};await refresh();toast(t('phoneConfirmed'));}
  if(id==='recovery-request-form'){const result=await api('/api/auth/recovery/request','POST',{phone:data.phone,language:lang});recoveryFlow={...result,phone:data.phone};render();toast(t('recoveryGeneric'));}
  if(id==='recovery-reset-form'){if(data.password!==data.confirmPassword)throw Error('passwordMismatch');await api('/api/auth/recovery/reset','POST',{challengeId:recoveryFlow.challengeId,code:data.code,password:data.password});recoveryFlow={};verificationFlow={};user=null;csrf='';actor='';groups=[];currentGroup='';state=blank();location.hash='login';render();toast(t('passwordRecovered'));}
 }catch(e){const err=form.querySelector('.error');if(err)err.textContent=errorMessage(e);else toast(errorMessage(e));}finally{busy=false;if(button.isConnected)button.disabled=false;startCodeTimer();}
}

let duesFilter='all';
paths.dues=paths.clock;
function trackingControls(s){return '<label class="full checkbox-label"><input name="trackContributions" type="checkbox" '+(s.trackContributions?'checked':'')+'>'+esc(t('trackContributions'))+'</label>'+field('dueDay','dueDay','number',s.dueDay||31,'required min="1" max="31" step="1"')+field('trackingStart','trackingStart','month',s.trackingStart||today().slice(0,7),'required')+'<div class="callout full">'+esc(t('planHelp'))+'</div>';}
function receiptLink(p){return p?.receipt?'<a class="btn ghost" href="/api/groups/'+encodeURIComponent(currentGroup)+'/receipts/'+encodeURIComponent(p.receipt)+'" download>'+icon('download')+esc(t('viewReceipt'))+'</a>':'';}
function dueTable(rows,loans=false){rows=rows.filter(r=>duesFilter==='all'||r.status==='overdue').sort((a,b)=>a.date.localeCompare(b.date));return rows.length?'<div class="table-wrap"><table><thead><tr>'+['name',loans?'installmentNumber':'period','deadline','expected','paid','remainingDue','status'].map(k=>'<th>'+esc(t(k))+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,200).map(r=>'<tr><td>'+person(r.member)+'</td><td>'+esc(loans?r.installment:r.period)+'</td><td>'+esc(r.date)+'</td><td>'+fmt(r.expected)+'</td><td>'+fmt(r.paid)+(r.credit?'<div class="statusline">'+esc(t('credit'))+': '+fmt(r.credit)+'</div>':'')+'</td><td class="amount">'+fmt(r.remaining)+' RWF</td><td>'+badge(r.status)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">'+esc(t('noRecords'))+'</div>';}
function duesPage(){const d=state.tracking;return heading(t('dues'),'duesSub',btn('record','payment','plus'))+'<div class="stats">'+stat('overdueContributions',amount(d.overdueContributions),'clock','confirmedOnly')+stat('overdueLoans',amount(d.overdueLoans),'loans','confirmedOnly')+'</div><div class="tabs"><button data-dues="all" class="'+(duesFilter==='all'?'active':'')+'">'+esc(t('allDues'))+'</button><button data-dues="overdue" class="'+(duesFilter==='overdue'?'active':'')+'">'+esc(t('overdueOnly'))+'</button></div>'+(!d.enabled?'<div class="callout">'+esc(t('trackingOff'))+'</div>':'')+'<section class="panel"><div class="panel-head"><h2>'+esc(t('contributionDues'))+'</h2><span class="sub">'+esc(d.asOf)+'</span></div>'+dueTable(d.contributions)+'</section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>'+esc(t('loanDues'))+'</h2></div>'+dueTable(d.installments,true)+'</section>';}
function reversalAction(e){return me().role==='chairperson'&&['contribution','repayment','disbursement','expense'].includes(e.kind)&&!state.ledger.some(r=>r.reverses===e.id)?btn('reverseRecord','reverseEntry','',true,'data-id="'+e.id+'"'):'';}
function reverseDialog(id){const e=state.ledger.find(e=>e.id===id);if(!e)return;dialog('reverseTitle','<p class="dialog-sub">'+esc(t('reverseHelp'))+'</p><h2>'+fmt(e.amount)+' RWF</h2><p class="sub">'+esc(e.date)+'</p><input type="hidden" name="id" value="'+e.id+'"><label style="margin-top:18px">'+esc(t('reason'))+'<textarea name="reason" required minlength="5" maxlength="300"></textarea></label><label class="checkbox-label" style="margin-top:15px"><input type="checkbox" required>'+esc(t('reverseConfirm'))+'</label>'+formActions('reverseSubmit'),'reverse-form');}
function reconciliationPanel(){if(!leader())return '';const records=state.reconciliations||[];return '<section class="panel" style="margin-top:22px"><div class="panel-head"><div><h2>'+esc(t('reconciliation'))+'</h2><p class="sub">'+esc(t('reconciliationHelp'))+'</p></div>'+(treasurer()?btn('recordBalanceCheck','reconcile','plus'):'')+'</div>'+(records.length?'<div class="table-wrap"><table><thead><tr>'+['date','recordedBalance','observedTotal','difference','notes'].map(k=>'<th>'+esc(t(k))+'</th>').join('')+'</tr></thead><tbody>'+records.map(r=>'<tr><td>'+esc(r.date)+'</td><td>'+fmt(r.recorded)+'</td><td>'+fmt(r.actual)+'</td><td class="amount">'+fmt(r.difference)+' RWF</td><td class="audit-detail">'+esc(r.note)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">'+esc(t('noRecords'))+'</div>')+'</section>';}
function reconcileDialog(){dialog('recordBalanceCheck','<p class="dialog-sub">'+esc(t('reconciliationHelp'))+'</p><div class="callout">'+esc(t('recordedBalance'))+': '+fmt(state.groupTotals.cash)+' RWF</div><div class="form-grid">'+field('countedCash','cash','number',0,'required min="0" max="1000000000000" step="1"')+field('countedMomo','momo','number',0,'required min="0" max="1000000000000" step="1"')+field('countedBank','bank','number',0,'required min="0" max="1000000000000" step="1"')+'<label class="full">'+esc(t('notes'))+'<textarea name="note" maxlength="300"></textarea></label></div>'+formActions(),'reconcile-form');}
function inboxDialog(){const items=state.notifications||[];dialog('notifications','<p class="dialog-sub">'+esc(t('inboxHelp'))+'</p>'+(items.length?items.map(n=>'<div class="task '+(n.read?'read-notice':'')+'"><span class="task-icon">'+icon(n.read?'check':'bell')+'</span><div><strong>'+esc(n.title||t(n.type))+'</strong>'+(n.message?'<p>'+esc(n.message)+'</p>':'')+'<p>'+(n.amount!=null?fmt(n.amount)+' RWF · ':'')+esc(n.date)+(n.status?' · '+esc(t(n.status)):'')+'</p></div></div>').join('')+'<div class="form-actions">'+btn('markRead','markRead','check',true)+'</div>':'<div class="empty">'+esc(t('noRecords'))+'</div>'));}
async function markNotices(){if(busy)return;busy=true;try{const result=await api('/api/groups/'+currentGroup+'/notifications/read','POST',{ids:(state.notifications||[]).map(n=>n.id)});state=result.state;modal.close();render();inboxDialog();}catch(e){toast(errorMessage(e));}finally{busy=false;}}
async function submitPaymentWithReceipt(form,data){
 if(busy)return;busy=true;const elements=Array.from(form.elements),file=form.elements.receiptFile?.files[0];elements.forEach(e=>e.disabled=true);
 try{delete data.receiptFile;
  if(file&&!form.dataset.receipt){if(!file.size||file.size>5*1024*1024)throw Error('receiptTooLarge');const key=form.dataset.uploadKey||=crypto.randomUUID();let response;try{response=await fetch('/api/groups/'+currentGroup+'/receipts',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf,'Idempotency-Key':key,'X-File-Name':encodeURIComponent(file.name),'Content-Type':file.type||'application/octet-stream'},body:file});}catch{throw Error('connectionError');}const r=await response.json();if(!response.ok)throw Error(r.error||'serverError');form.dataset.receipt=r.id;}
  if(form.dataset.receipt)data.receipt=form.dataset.receipt;
  busy=false;await mutate('payment.submit',{...data,amount:Number(data.amount)},'paymentSent',form);
 }catch(e){const err=form.querySelector('.error');if(err)err.textContent=errorMessage(e);else toast(errorMessage(e));}finally{busy=false;elements.forEach(e=>e.disabled=false);}
}
document.addEventListener('change',e=>{if(e.target.name==='receiptFile'){discardDraftReceipt();delete e.target.form.dataset.receipt;delete e.target.form.dataset.uploadKey;}});

function discardDraftReceipt(){const f=modal.querySelector('#payment-form');if(!busy&&f?.dataset.receipt)api('/api/groups/'+currentGroup+'/receipts/'+encodeURIComponent(f.dataset.receipt),'DELETE',{}).catch(()=>{});}

function duesSummary(){const d=state.tracking;if(!d||!(d.overdueContributions+d.overdueLoans))return '';return '<div class="callout split"><span>'+esc(t('overdueContributions'))+': '+fmt(d.overdueContributions)+' RWF · '+esc(t('overdueLoans'))+': '+fmt(d.overdueLoans)+' RWF</span><button class="btn ghost" data-route="dues">'+esc(t('dues'))+' →</button></div>';}
function announcementsPanel(){const rows=state.announcements||[];return '<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>'+esc(t('announcements'))+'</h2>'+(['chairperson','secretary'].includes(me().role)?btn('publishAnnouncement','publishAnnouncement','plus'):'')+'</div>'+(rows.length?rows.map(r=>'<article class="task"><div><strong>'+esc(r.title)+'</strong><p style="white-space:pre-wrap">'+esc(r.message)+'</p><p>'+esc(member(r.actor).name)+' · '+esc(r.createdAt.slice(0,10))+'</p></div></article>').join(''):'<div class="empty">'+esc(t('noRecords'))+'</div>')+'</section>';}
function announcementDialog(){dialog('publishAnnouncement',field('announcementTitle','title','text','','required maxlength="80"')+'<label style="margin-top:16px">'+esc(t('announcementBody'))+'<textarea name="message" required maxlength="1000"></textarea></label>'+formActions('publishAnnouncement'),'announcement-form');}
modal.addEventListener('cancel',()=>discardDraftReceipt());

function membershipInvites(){if(me().role!=='chairperson')return '';return '<section class="panel"><div class="panel-head"><h2>'+esc(t('pendingInvites'))+'</h2></div><div class="table-wrap"><table><tbody>'+(state.invitations||[]).map(i=>'<tr><td>'+esc(i.phone)+'</td><td>'+esc(t(i.role))+'</td><td>'+esc(new Date(i.expiresAt).toLocaleString(lang))+'</td><td>'+btn('revokeInvite','revokeInvite','',true,'data-id="'+esc(i.id)+'"')+'</td></tr>').join('')+'</tbody></table></div></section>';}
function manageMemberDialog(id){const m=member(id);dialog('manageMember','<p>'+esc(m.name)+' · '+esc(t(m.role))+'</p><div class="callout">'+esc(t('membershipInfo'))+'</div><input type="hidden" name="id" value="'+esc(id)+'">'+selectField('operation','operation',option('role',t('changeRole'))+option('transfer',t('transferChair')))+selectField('role','role',['member','treasurer','secretary'].map(r=>option(r,t(r),r===m.role)).join(''))+field('reason','reason','text','','required minlength="5" maxlength="300"')+'<label><input type="checkbox" name="confirm"> '+esc(t('transferConfirm'))+'</label>'+formActions('save')+(m.role==='member'&&m.status!=='exited'?btn('memberStatus','memberStatus','',true,'data-id="'+esc(id)+'"'):''),'member-role-form');}
function revokeInviteDialog(id){dialog('revokeInvite','<p>'+esc(t('revokeInfo'))+'</p><input type="hidden" name="id" value="'+esc(id)+'">'+formActions('revokeInvite'),'revoke-invite-form');}

function expensePanel(){if(!leader())return '';return '<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>'+esc(t('expenses'))+'</h2>'+btn('newExpense','newExpense')+'</div><p class="sub">'+esc(t('expenseHelp'))+'</p><div class="table-wrap"><table><tbody>'+(state.expenses||[]).map(e=>'<tr><td>'+esc(e.date)+'</td><td>'+esc(e.payee)+'<br>'+esc(e.description)+'</td><td>'+fmt(e.amount)+' RWF</td><td>'+esc(t(e.status))+'</td><td>'+(e.status==='pending'&&me().role==='chairperson'?btn('reviewExpense','reviewExpense','',true,'data-id="'+esc(e.id)+'"'):e.status==='approved'&&treasurer()?btn('payExpense','payExpense','',true,'data-id="'+esc(e.id)+'"'):'')+'</td></tr>').join('')+'</tbody></table></div></section>';}
function expenseDialog(){dialog('newExpense',field('amount','amount','number','','required min="1" max="1000000000" step="1"')+field('payee','payee','text','','required maxlength="100"')+field('expenseDescription','description','text','','required minlength="5" maxlength="300"')+formActions('save'),'expense-form');}
function expenseReviewDialog(id){dialog('reviewExpense','<input type="hidden" name="id" value="'+esc(id)+'">'+selectField('status','decision',option('approved',t('approved'))+option('rejected',t('rejected')))+field('reason','reason','text','','maxlength="300"')+formActions('save'),'expense-review-form');}
function expensePayDialog(id){const e=state.expenses.find(x=>x.id===id);dialog('payExpense','<p>'+esc(e.payee)+' · '+fmt(e.amount)+' RWF</p><div class="callout">'+esc(t('expenseHelp'))+'</div><input type="hidden" name="id" value="'+esc(id)+'">'+field('reference','reference','text','','required maxlength="100"')+'<label><input type="checkbox" required> '+esc(t('expenseConfirm'))+'</label>'+formActions('save'),'expense-pay-form');}

function memberStatusDialog(id){const m=member(id);dialog('memberStatus','<p>'+esc(m.name)+'</p><div class="callout">'+esc(t('statusHelp'))+'</div><input type="hidden" name="id" value="'+esc(id)+'">'+selectField('status','status',['active','suspended','exited'].filter(x=>x!==m.status).map(x=>option(x,t(x))).join(''))+field('reason','reason','text','','required minlength="5" maxlength="300"')+'<label><input type="checkbox" required> '+esc(t('statusConfirm'))+'</label>'+formActions('save'),'member-status-form');}

function memberSavings(id){return state.ledger.filter(e=>e.member===id).reduce((n,e)=>{const k=e.kind==='reversal'?e.originalKind:e.kind;return n+(e.kind==='reversal'?-1:1)*e.amount*(k==='contribution'?1:k==='withdrawal'?-1:0);},0);}
function settlementPanel(){return '<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>'+esc(t('settlement'))+'</h2>'+(me().status!=='exited'?btn('withdrawalRequest','withdrawalRequest'):'')+'</div><p class="sub">'+esc(t('settlementHelp'))+'</p><div class="table-wrap"><table><thead><tr><th>'+esc(t('name'))+'</th><th>'+esc(t('remainingSavings'))+'</th></tr></thead><tbody>'+state.members.filter(m=>leader()||m.id===actor).map(m=>'<tr><td>'+esc(m.name)+'</td><td>'+fmt(memberSavings(m.id))+' RWF</td></tr>').join('')+'</tbody></table><table><tbody>'+(state.withdrawals||[]).map(w=>'<tr><td>'+esc(member(w.member).name)+'</td><td>'+fmt(w.amount)+' RWF</td><td>'+esc(t(w.status))+'</td><td>'+esc(w.reference||w.reason)+'</td><td>'+(w.status==='pending'&&me().role==='chairperson'?btn('withdrawalReview','withdrawalReview','',true,'data-id="'+esc(w.id)+'"'):w.status==='approved'&&me().role==='chairperson'?btn('cancel','withdrawalCancel','',true,'data-id="'+esc(w.id)+'"'):w.status==='approved'&&treasurer()?btn('withdrawalPay','withdrawalPay','',true,'data-id="'+esc(w.id)+'"'):'')+'</td></tr>').join('')+'</tbody></table></div></section>';}
function withdrawalDialog(){dialog('withdrawalRequest',field('amount','amount','number','','required min="1" max="1000000000" step="1"')+field('reason','reason','text','','required minlength="5" maxlength="300"')+formActions('save'),'withdrawal-form');}
function withdrawalReviewDialog(id){dialog('withdrawalReview','<input type="hidden" name="id" value="'+esc(id)+'">'+selectField('status','decision',option('approved',t('approved'))+option('rejected',t('rejected')))+field('reason','reason','text','','maxlength="300"')+formActions('save'),'withdrawal-review-form');}
function withdrawalPayDialog(id){const w=state.withdrawals.find(w=>w.id===id);dialog('withdrawalPay','<p>'+esc(member(w.member).name)+' · '+fmt(w.amount)+' RWF</p><p>'+esc(t('settlementHelp'))+'</p><input type="hidden" name="id" value="'+esc(id)+'">'+field('reference','reference','text','','required maxlength="100"')+'<label><input type="checkbox" required> '+esc(t('expenseConfirm'))+'</label>'+formActions('save'),'withdrawal-pay-form');}

function withdrawalCancelDialog(id){dialog('cancel','<input type="hidden" name="id" value="'+esc(id)+'">'+field('reason','reason','text','','required minlength="5" maxlength="300"')+formActions('save'),'withdrawal-cancel-form');}
